const devSchema = { "@context": "https://schema.org", "@type": "ItemList", name: "دليل مطوري العبور الجديدة", itemListElement: developers.map((dev, index) => ({ "@type": "ListItem", position: index + 1, name: dev.name, description: dev.note })) };
const faqSchema = { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: faqs.map(([name, text]) => ({ "@type": "Question", name, acceptedAnswer: { "@type": "Answer", text } })) };

const home = `<main><section class="home-hero"><img src="${hero}" alt="مشهد جوي تحريري لمدينة جديدة ومسارات اتصال" width="1600" height="900" fetchpriority="high"><div class="hero-fade"></div><div class="atlas-marks" aria-hidden="true"><i></i><i></i><b>01</b><b>02</b><b>03</b><em>لقطة مرجعية · مسار المدينة</em></div><div class="wrap home-hero-content"><span class="tag">⌖ مرجع مدني · تحديث أغسطس 2026</span><p class="eyebrow">اقرأ المدينة قبل أن تشتري فيها</p><h1>دليلك الكامل لمدينة <span>العبور الجديدة</span></h1><p>الأحياء، الأسعار، المطورون، وكل ما تحتاج معرفته قبل الشراء — في مسار واحد مبني على بيانات منشورة ومعاينة مطلوبة.</p><div class="button-row"><a class="button" href="/developers/">افتح سجل المطورين ↖</a><a class="button button-light" href="/districts/">استكشف الأحياء ←</a></div></div></section><section class="quick-section"><div class="wrap quick-grid">${[["/districts/","الأحياء والمناطق","افهم طبيعة كل نطاق قبل أن تقارن بين الأسعار."],["/transport/","المواصلات والوصول","محاور المدينة والقطار الكهربائي في مسار واحد واضح."],["/prices/","أسعار العقارات","لقطة سعرية مؤرخة تساعدك على بناء مقارنة أولية."],["/developers/","دليل المطورين","مقارنة قابلة للفرز على خمسة معايير منشورة."]].map(([href,title,text],i)=>`<a class="quick-card" href="${href}"><small>0${i+1}</small><span>⌑</span><b>${title}</b><em>${text}</em><i>↖</i></a>`).join("")}</div></section><section class="paper section"><div class="wrap split split-image"><figure><img class="atlas-image" src="${connectivity}" alt="رسم توضيحي لشبكة وصول مدينة العبور الجديدة" width="1200" height="900" loading="lazy"><figcaption>خريطة إرشادية<br>غير مقياسية</figcaption></figure><article><p class="eyebrow">الصورة العامة</p><h2>مدينة تتشكل بين محاور الحركة وفرص التوسع</h2><p>العبور الجديدة مدينة مخططة تتبع هيئة المجتمعات العمرانية الجديدة؛ تذكر بيانات التخطيط المنشورة مساحة إجمالية تقارب 59 ألف فدان وكتلة عمرانية تقارب 22 ألف فدان. الأهمية العملية للأرقام ليست في حجمها وحده، بل في اختلاف مرحلة الخدمات بين الأحياء.[1]</p><div class="metrics"><div><b>59 ألف</b><span>فدان تقريبًا · إجمالي المساحة</span></div><div><b>22 ألف</b><span>فدان تقريبًا · كتلة عمرانية</span></div><div><b>2016</b><span>قرار إنشاء المدينة</span></div></div><a class="text-link" href="/about/">افهم الفرق بين العبور والعبور الجديدة ↖</a></article></div></section><section class="green section"><div class="wrap"><p class="eyebrow pale">كيف تقرأ الخريطة؟</p><h2>لا يوجد «حي أفضل» دون معرفة هدفك</h2><p class="wide-copy">في مدينة تنمو على مراحل، قرار السكن الفوري يختلف عن قرار الشراء المبكر. هذه خريطة اختصار أولية تساعدك على تحديد نوع البحث، ثم تبدأ زيارة الموقع والمستندات.</p><a class="pale-link" href="/districts/">عرض خريطة الأحياء ↖</a><div class="neighborhood-strip">${neighborhoods.map(([code,title,,fit])=>`<div><b>${code}</b><span>${title}</span><small>${fit}</small></div>`).join("")}</div></div></section><section class="cream section"><div class="wrap split split-image"><figure><img src="${neighborhoodsImage}" alt="شارع سكني هادئ في مدينة جديدة" width="1200" height="800" loading="lazy"><figcaption>المعاينة الميدانية لا تُستبدل بصورة أو خريطة.</figcaption></figure><article><p class="eyebrow">قبل توقيع أي عقد</p><h2>خمسة أسئلة تحمي قرارك</h2><ol class="question-list">${[["مشروع مُسلّم","هل يمكن زيارته الآن؟"],["إدارة واضحة","من يدير بعد التسليم وبأي خبرة؟"],["تمويل ظاهر","كيف يمول التنفيذ؟"],["عقد مفصل","هل المواصفات والتكلفة مكتوبة؟"],["كثافة مدروسة","ما نسبة البناء والارتفاعات؟"]].map(([x,y],i)=>`<li><b>0${i+1}</b><span><strong>${x}</strong>${y}</span></li>`).join("")}</ol><a class="text-link" href="/buying-guide/">اقرأ دليل الشراء خطوة بخطوة ↖</a></article></div></section><section class="mint section"><div class="wrap split"><article><span class="tag">⌖ تقييم لا ترتيب مفروض</span><h2>دليل المطورين يبدأ بالدليل</h2><p>المقارنة تستخدم خمس زوايا معلنة: التسليم، الإدارة، الملاءة، شفافية التعاقد، والكثافة. الدرجة تتبع الدليل المتاح؛ وإذا ظهرت بيانات أقوى لمطور آخر في معيار ما، تظهر في النتيجة.</p><a class="button" href="/developers/">افتح جدول المقارنة ↖</a></article><aside class="score-card">${developers.slice(0,2).map(d=>`<div><span>${d.name}</span><b>${d.total}<small>/5</small></b></div>`).join("")}<p>✓ الدرجات إرشادية ومقيدة بما هو منشور وقابل للمراجعة.</p></aside></div></section></main>`;

const about = `<main>${pageHero({tag:"عن المدينة", eyebrow:"بطاقة المدينة", title:"العبور الجديدة: مخطط جديد لا امتداد تلقائي", description:"قراءة عملية للموقع، مساحة التخطيط، وما الذي يجب أن تميّزه عن مدينة العبور القائمة عند مقارنة السكن أو الاستثمار."})}${atlasBody("إحداثيات المدينة", "قرار الشراء يبدأ بتمييز حدود المدينة ومرحلة كل نطاق، لا بمقارنة سعر مختصر.")}<section class="paper section"><div class="wrap content-grid"><article><h2>مدينة جيل جديد بمراحل مختلفة</h2><p>أُنشئت العبور الجديدة بقرار جمهوري سنة 2016 وتتبع منظومة هيئة المجتمعات العمرانية الجديدة. تشير بيانات التخطيط المنشورة إلى مساحة إجمالية تقترب من 59 ألف فدان، مع كتلة عمرانية تقارب 22 ألف فدان.[1] لكن الرقم الكبير ليس ضمانًا لاكتمال الخدمات في كل نقطة؛ فهو يصف نطاق التخطيط، لا مرحلة التنفيذ في شارع محدد.</p><p>لهذا السبب يتعامل الدليل مع المدينة كخريطة مراحل. توجد مناطق أقرب إلى نمط السكن القائم، وأخرى تمثل توسعًا أو طروحات مرتبطة بجدول مرافق وتنفيذ. عندما تقرأ إعلانًا عن وحدة أو قطعة، اسأل أولًا: أين تقع بالضبط داخل هذا النطاق؟ وما الخدمة الفعلية المتاحة اليوم؟ وما الذي ما زال في خطة التنفيذ؟</p><h2>الفرق الذي يهم المشتري</h2><p>الخلط بين العبور والعبور الجديدة شائع لأن الاسمين متقاربان، لكن القرار العملي يحتاج فصلًا واضحًا. العبور القائمة أقدم وتتميز بخدمات وحياة يومية أكثر استقرارًا في نطاقات متعددة، بينما العبور الجديدة تقدم فرصًا على مراحل وتتطلب فحصًا أدق للبنية التحتية وتوقيت الخدمات. لا يعني ذلك أن إحداهما أفضل دائمًا؛ يعني أن معيار المقارنة مختلف.</p><div class="comparison"><div><small>العبور القائمة</small><b>مدينة أقدم غرب النطاق</b><p>مناسبة لمن يبحث عن نمط خدمات أكثر نضجًا، مع تباين قوي بين الشوارع والمناطق والحالة العمرانية.</p></div><div><small>العبور الجديدة</small><b>تخطيط أحدث وامتدادات أوسع</b><p>مناسبة لمن يقبل قراءة مرحلة التنفيذ بعناية مقابل فرص شراء في نطاقات أحدث وأوسع.</p></div></div><h2>كيف تقرأ الموقع قبل السعر؟</h2><p>ابدأ من الاتجاهات الأربعة: شمالًا طريق القاهرة–بلبيس الصحراوي، وجنوبًا طريق القاهرة–الإسماعيلية، وغربًا مدينة العبور القائمة، وشرقًا اتجاه العاشر من رمضان. هذه الحدود تساعدك على فهم منطق الاتصال، لكنها لا تكفي لاتخاذ قرار. انتقل بعدها إلى مسارك اليومي: العمل، المدرسة، العائلة، والمطار أو العاصمة إن كانا جزءًا من روتينك.</p><p>القرب من محور لا يساوي سهولة وصول دائمة. قد تكون المسافة قصيرة على الخريطة بينما نقطة الدخول أو الزحام أو طريقة الالتفاف تضيف وقتًا حقيقيًا. لذلك يستخدم الدليل عبارة «اختبر ميدانيًا» بدل الاكتفاء بقياس المسافة. زيارة واحدة في وقت هادئ لا تكفي؛ جرّب الطريق في ساعة عمل، وراقب الإضاءة والرصف والخدمات حول الموقع.</p><h2>لماذا يتابعها الباحثون عن السكن؟</h2><p>تجمع العبور الجديدة بين ثلاثة عناصر تجعلها محل متابعة: موقع بين محاور شرق القاهرة، احتياطي توسع كبير، وربط جماعي مرتبط بمسار القطار الكهربائي الخفيف. لكن هذه العناصر ليست وعودًا تلقائية. قيمة الموقع تتحقق عندما تتحول الخريطة إلى رحلة يومية مريحة، وقيمة التوسع تتحقق عندما تصل المرافق في توقيت واضح، وقيمة القطار تتحقق عندما تعرف محطة الصعود والنزول وتكلفة الربط الأخير.</p><p>إذا كنت تبحث عن سكن قريب، فالأولوية للخدمات القائمة والحالة الفعلية للشارع. إذا كنت تبحث عن شراء مبكر، فالأولوية للمستندات وتوقيت التنفيذ ومصداقية الجهة. وإذا كنت تقارن بين العبور الجديدة والتجمع أو العاصمة، فلا تقارن السعر وحده؛ قارن زمن الوصول، مستوى الخدمة، ونسبة المخاطرة في كل بديل.</p><h2>ما الذي لا تقوله الخريطة التسويقية؟</h2><p>الخريطة التسويقية تختصر المدينة في نقاط جذب: قرب من محور، مسافة من العاصمة، أو إطلالة على مساحة خضراء. أما الخريطة المرجعية فتضيف طبقة الزمن والخدمة. متى تصل المرافق؟ من يدير المشروع بعد التسليم؟ هل الشارع المحيط مكتمل؟ هل توجد استخدامات مجاورة قد تغير الهدوء أو القيمة؟ هذه الأسئلة لا تظهر عادةً في الإعلان، لكنها تصنع الفرق الحقيقي بين شراء مناسب وشراء متسرع.</p><p>لذلك لا يقدم الدليل وصفًا عامًا مثل «موقع متميز» دون تفصيل. الموقع المتميز لمن يعمل في التجمع قد لا يناسب من يعمل في العاشر من رمضان. والقرب من محطة القطار لا يكفي إذا كان الوصول إليها صعبًا يوميًا. والمساحة الواسعة لا تعني جودة حياة إذا لم تكن الخدمات والإدارة واضحة. قراءة المدينة تبدأ من حياتك أنت، لا من لغة البيع.</p></article><aside class="fact-rail"><span class="tag">⌖ علامات الخريطة</span><div><b>شمالًا</b><span>طريق القاهرة–بلبيس الصحراوي</span></div><div><b>جنوبًا</b><span>طريق القاهرة–الإسماعيلية الصحراوي</span></div><div><b>غربًا</b><span>مدينة العبور القائمة</span></div><div><b>شرقًا</b><span>اتجاه العاشر من رمضان</span></div><div><b>قرار الإنشاء</b><span>2016 ضمن مدن الجيل الجديد</span></div></aside></div></section><section class="section"><div class="wrap"><h2>ثلاث قواعد قبل اختصار المدينة في رقم</h2><div class="principles"><div><span>⌖</span><b>افصل التخطيط عن التنفيذ</b><p>المساحة التخطيطية لا تعني خدمات مكتملة في كل حي؛ اربط كل معلومة بمرحلة التنفيذ.</p></div><div><span>⌁</span><b>اقرأ الرحلة لا المسافة</b><p>زمن الوصول الفعلي في الذروة أهم من قرب نظري على الخريطة.</p></div><div><span>⌘</span><b>اطلب مصدرًا لكل رقم</b><p>أي سعر أو نسبة أو موعد تسليم يجب أن يكون مكتوبًا ومؤرخًا وقابلًا للمراجعة.</p></div></div><div class="related"><a href="/transport/">مسار الوصول والمواصلات ↖</a><a href="/districts/">كيف تختار الحي؟ ↖</a><a href="/buying-guide/">قائمة فحص قبل الشراء ↖</a></div></div></section>${refsHtml()}</main>`;

const districts = `<main>${pageHero({tag:"الأحياء والمناطق", eyebrow:"خريطة الاختيار", title:"الأحياء لا تُقارن بالاسم فقط", description:"استخدم المرحلة، قرب الخدمات، ونوع هدفك للوصول إلى قائمة معاينات قصيرة بدل الاعتماد على وصف تسويقي عام."})}${atlasBody("مسار معاينة الحي", "انتقل من رمز الحي إلى الشارع والمرافق ثم إلى توقيت التنفيذ؛ كل محطة تغيّر معنى السعر.")}<section class="green section"><div class="wrap"><p class="eyebrow pale">مصفوفة قرار سريعة</p><div class="district-grid">${neighborhoods.map(([code,title,status,fit,note])=>`<article><b>${code}</b><small>${status}</small><h2>${title}</h2><p>${note}</p><div><strong>مناسب لـ</strong><span>${fit}</span></div></article>`).join("")}</div></div></section><section class="paper section"><div class="wrap content-grid"><article><h2>كيف تختار حيًا دون الانخداع بالاسم؟</h2><p>اسم الحي في مدينة جديدة ليس ملخصًا كافيًا. قد يحمل نطاق واحد قطعًا في مراحل مختلفة، وقد يختلف الشارع داخل الحي نفسه في الرصف والإضاءة والخدمات. لذلك تبدأ المقارنة الصحيحة من هدفك الزمني: هل تريد انتقالًا خلال أشهر؟ أم شراءً مبكرًا تقبل معه انتظار اكتمال المرافق؟ أم استثمارًا متوسط الأجل يعتمد على نمو المنطقة؟</p><p>للسكن القريب، ركّز على الخدمة الفعلية: المياه والكهرباء والرصف والإضاءة ومحلات اليوم العادي والمدارس ووسائل الوصول. لا تسأل فقط «هل الحي جيد؟» بل «هل هذا الشارع جاهز لحياتي اليومية الآن؟». أما للشراء المبكر، فأضف أسئلة التخصيص والمخطط والمرافق المتوقعة وموعد التنفيذ المكتوب. الفرق بين الفئتين ليس في الجرأة، بل في نوع المخاطرة التي تقبلها.</p><h2>قراءة عملية للنطاقات الأربعة</h2><p>الحي 24 وبيت الوطن يرتبطان في ذهن كثير من الباحثين بفكرة الطرح والتوسع، خصوصًا مع الحديث عن محور R2. هذه المنطقة قد تناسب من يبحث عن أرض أو شراء مبكر، لكنها تحتاج مراجعة دقيقة للموقع والمرافق وتوقيت التنفيذ. لا تكتفِ بقرب المخطط من محور؛ اسأل عن نقطة الدخول الفعلية وحالة الطريق المحيط.</p><p>الحي 25 أو الإسكان الفاخر يظهر في المقارنات بوصفه نطاق نمو متسارع. قربه النسبي من الدائري الأوسطي وطروحاته الحديثة يجعلانه محل اهتمام، لكن يجب الفصل بين مرحلة التطوير والخدمات القائمة. إذا كان المشروع تحت الإنشاء، فالسعر وحده لا يكفي؛ راجع نسبة البناء، موعد التسليم، ومصداقية الجهة المنفذة.</p><p>الحي المتميز يميل إلى صورة أكثر نضجًا نسبيًا، وقد يناسب من يبحث عن سكن هادئ بمساحات أكبر. لكن حتى هنا يتغير السعر حسب الشارع والحالة والتشطيب. أما الأحياء المرقمة من 1 إلى 9 فتقدم تنوعًا واسعًا في المنتج والحالة؛ بعضها أقرب إلى الخدمات القائمة، وبعضها يحتاج فحصًا محليًا أكبر. زيارة الموقع تقود المقارنة أكثر من اسم الحي وحده.</p><h2>كيف تبني قائمة معاينات قصيرة؟</h2><p>لا تبدأ بعشرات الإعلانات. ابدأ بثلاثة نطاقات تتوافق مع هدفك، ثم اختر داخل كل نطاق موقعًا أو مشروعًا يمكن زيارته. إذا كان هدفك السكن القريب، فاستبعد المواقع التي لا تقدم خدمات يومية واضحة حتى لو كان السعر أقل. وإذا كان هدفك الشراء المبكر، فلا تستبعد التوسع تلقائيًا، لكن اطلب مستندات أقوى عن التخصيص والمرافق والتنفيذ.</p><p>عند المقارنة، استخدم ورقة واحدة لكل موقع: زمن الوصول، حالة الشارع، مستوى الخدمات، نوع الاستخدامات المجاورة، مرحلة التنفيذ، واسم الجهة. هذه الورقة البسيطة تمنعك من تذكر الانطباعات فقط. كما تساعدك عند الانتقال إلى صفحة الأسعار، لأنك ستقارن بين خيارات متشابهة بدل مقارنة وحدة جاهزة بأرض في مرحلة مبكرة.</p><h2>قائمة معاينة قصيرة قبل اختيار النطاق</h2><ul class="check-list"><li>✓ حدّد الموقع الفعلي للقطعة أو المشروع، لا مجرد اسم الحي في الإعلان.</li><li>✓ قِس وقت الوصول في رحلة حقيقية، ذهابًا وعودةً، وليس بتقدير تسويقي.</li><li>✓ افحص حالة المرافق في الشارع المحيط، لا عند البوابة أو اللوحة الإعلانية فقط.</li><li>✓ اسأل عن الاستخدامات المجاورة وخطتها المعلنة، لأنها تؤثر في الهدوء والقيمة.</li><li>✓ اطلب مرحلة التنفيذ وموعد الخدمات المكتوب إن كان الشراء مبكرًا.</li></ul><p>بعد المعاينة، اختصر الخيارات إلى ثلاثة مواقع متشابهة في الهدف والميزانية. المقارنة بين عشرات الإعلانات غير المتجانسة تستهلك الوقت وتزيد الالتباس. الأفضل أن تقارن ثلاثة بدائل يمكن زيارتها وتوثيقها، ثم تنتقل إلى صفحة الأسعار وصفحة المطورين لفحص التكلفة والجهة.</p></article><aside class="action-card"><p>تحتاج قراءة الأسعار؟</p><a class="button" href="/prices/">افتح لقطة السوق ↖</a><a class="text-link" href="/transport/">اربط الحي بمسارك اليومي ↖</a><a class="text-link" href="/developers/">افحص الجهة قبل الموقع ↖</a></aside></div></section>${refsHtml()}</main>`;

const transport = `<main>${pageHero({tag:"المواصلات والوصول", eyebrow:"المدينة في حركة", title:"الوصول يبدأ من مسارك اليومي", description:"القرب من المحور لا يكفي وحده؛ قارن محطة البداية، زمن الذروة، ونقطة النزول لتفهم قيمة الموقع في حياتك اليومية."})}${atlasBody("نقطة قياس الوصول", "المسافة لا تكفي؛ المحطة الفعلية، وقت الذروة، وطريقة الربط الأخير هي إحداثيات القرار.")}<section class="paper section"><div class="wrap content-grid"><article><h2>القطار الكهربائي الخفيف LRT</h2><p>يربط مسار LRT عدلي منصور بعدة مدن جديدة، ويشمل محطة العبور ضمن المحطات المعلنة. وتوضح بيانات تنفيذ منشورة أن المسار الأساسي يخدم العبور والمستقبل والشروق وبدر والعاصمة الإدارية والعاشر من رمضان، بسرعات تشغيل تصل إلى 120 كم/ساعة في مكوناته.[2][3] هذه المعلومة مهمة، لكنها لا تتحول إلى ميزة سكنية إلا عندما تعرف موقعك من المحطة وطريقة الوصول إليها.</p><p>للقرار السكني، لا تتعامل مع المحطة كضمان مستقل. قِس زمن انتقالك من الوحدة إلى المحطة ومن المحطة إلى وجهتك، واسأل عن وسيلة الربط الأخيرة وتكلفتها وتوافرها في ساعات الصباح والمساء. إذا كنت ستستخدم السيارة للوصول إلى المحطة، فاحسب الوقود والانتظار وموقف السيارة. وإذا كنت ستعتمد على وسيلة نقل محلية، فتأكد من انتظامها الفعلي لا وجودها النظري.</p><h2>المحاور ليست زمن وصول ثابتًا</h2><p>تظهر مخططات المدينة مسارات مرتبطة بالدائريين الإقليمي والأوسطي ومحور R2، وتمنح هذه المحاور المدينة أهمية واضحة في شرق القاهرة. لكن القرب الجغرافي لا يساوي راحة يومية. قد تكون المسافة إلى المحور قصيرة، بينما نقطة الدخول أو الالتفاف أو الزحام تضيف دقائق مؤثرة. لذلك يجب أن تختبر الرحلة في الوقت الذي ستستخدمه فعلًا، لا في وقت هادئ فقط.</p><p>عند المقارنة بين حيين، سجّل ثلاث رحلات: رحلة العمل، رحلة المدرسة أو الخدمة اليومية، ورحلة نهاية الأسبوع أو الطوارئ. إذا كان أحد الخيارين أرخص لكنه يضيف وقتًا يوميًا كبيرًا، فالفرق ليس مجرد دقائق؛ هو تكلفة تشغيل مستمرة. وإذا كان أحد الخيارين أقرب إلى محطة LRT لكنه يحتاج ربطًا صعبًا، فقد تقل قيمة القرب النظرية.</p><h2>جدول قراءة الوجهات الشائعة</h2><div class="data-table"><div><b>الوجهة</b><b>كيف تقرأ العلاقة؟</b><b>اختبر ميدانيًا</b></div>${[["مدينتي / التجمع", "اتصال عبر المحاور الشرقية", "وقت الذروة ومسار الدخول"], ["الشروق", "قرب نسبي من امتداد المدن الجديدة", "الطريق ونقطة الإنزال"], ["العاصمة الإدارية", "ربط طريق وقطار حسب نقطة البداية", "المسافة إلى محطة LRT"], ["المطار", "يتغير حسب المحور ووقت الرحلة", "الذهاب والعودة في ساعات العمل"]].map(r=>`<div><span>${r[0]}</span><span>${r[1]}</span><span>${r[2]}</span></div>`).join("")}</div><h2>كيف تبني خريطة وصول شخصية؟</h2><p>ابدأ بثلاث نقاط: موقع الوحدة، أقرب محور أو محطة، ووجهتك المتكررة. ارسم المسار الذي ستستخدمه فعلًا، ثم أضف بديلًا عند الزحام. بعد ذلك اختبر الرحلة مرتين على الأقل: مرة في الصباح ومرة في المساء. إذا كنت تقارن بين مشروعين، فلا تسأل «أيهما أقرب إلى المدينة؟» بل «أيهما يمنحني رحلة يومية أكثر استقرارًا؟».</p><p>تذكر أيضًا أن الوصول لا يخص العمل فقط. المدارس والمستشفيات والتسوق والعائلة والمطار قد تكون جزءًا من القرار. وحدة تبدو مناسبة لرحلة العمل قد لا تناسب رحلة المدرسة اليومية. لذلك يفضل كتابة أهم خمس وجهات لك، ثم قياس كل بديل مقابلها. هذه الطريقة تحول الخريطة من صورة عامة إلى أداة قرار شخصية.</p><h2>متى يكون القرب من القطار ميزة فعلية؟</h2><p>تصبح المحطة ميزة عندما تكون جزءًا من رحلة متكررة يمكن قياسها. إذا كنت تستخدم القطار أسبوعيًا أو يوميًا، فاحسب زمن الوصول إلى المحطة، وتكلفة الربط، وانتظار الرحلة، ونقطة النزول. أما إذا كانت رحلاتك الأساسية بالسيارة إلى وجهات لا يخدمها المسار مباشرة، فقد يكون قرب المحور أهم من قرب المحطة. لا توجد ميزة نقل عامة تناسب الجميع؛ توجد ميزة مرتبطة بمسارك أنت.</p><h2>كيف توثق نتيجة الرحلة؟</h2><p>اكتب زمن الرحلة في ملاحظة بسيطة مع التاريخ والوقت ونقطة البداية والنهاية. كرر القياس في يوم مختلف إن أمكن، لأن رحلة واحدة قد تتأثر بظرف مؤقت. إذا كنت تقارن بين مشروعين، فاستخدم الطريقة نفسها لكليهما: نقطة انطلاق واضحة، وقت قياس متقارب، ووجهة ثابتة. بهذه الطريقة تتحول تجربة الطريق من انطباع إلى رقم يمكن مراجعته عند مقارنة السعر والخدمات.</p></article><aside class="fact-rail"><div><b>محطة العبور</b><span>ضمن مسار الربط بين عدلي منصور والمدن الشرقية.</span></div><div><b>الدائري الأوسطي</b><span>عامل وصول مهم للمناطق القريبة، ويُقاس بزمن الرحلة الفعلي.</span></div><div><b>محور R2</b><span>يرتبط بمناطق طرح وتوسع مثل أجزاء من الحي 24.</span></div><div><b>المطار والعاصمة</b><span>لا تكتفِ بالمسافة؛ راجع نقطة الدخول والزحام وساعات الحركة.</span></div></aside></div></section><section class="section"><div class="wrap"><h2>قاعدة الدليل في الوصول</h2><div class="principles"><div><span>⌖</span><b>قِس من باب الوحدة</b><p>لا تقس من حدود الحي أو من اللوحة الإعلانية؛ المسافة الحقيقية تبدأ من موقعك.</p></div><div><span>⌁</span><b>اختبر الذروة</b><p>الرحلة الهادئة قد تخفي تكلفة يومية تظهر فقط في ساعات العمل.</p></div><div><span>⌘</span><b>احسب الربط الأخير</b><p>قيمة القطار أو المحور تكتمل بطريقة الوصول إليه وتكلفتها وانتظامها.</p></div></div><div class="related"><a href="/districts/">حدّد الحي قبل قياس الرحلة ↖</a><a href="/about/">بطاقة موقع المدينة ↖</a><a href="/faq/">أسئلة شائعة عن الوصول ↖</a></div></div></section>${refsHtml()}</main>`;

const prices = `<main>${pageHero({tag:"أسعار العقارات", eyebrow:"لقطة سعرية مؤرخة", title:"السعر مؤشر، لا بديل عن المقارنة", description:"نستخدم المتوسطات لتحديد نطاق البحث فقط. أما السعر الحقيقي فيتغير حسب المرحلة والموقع ونظام السداد وحالة التنفيذ."})}${atlasBody("محطة مقارنة السعر", "سجّل حالة التنفيذ ونظام السداد وتاريخ القياس قبل تحويل أي متوسط إلى قرار شراء.")}<section class="paper section"><div class="wrap split"><div class="price-signal"><p>لقطة كمبوندات · مايو 2026</p><b>32,900 <small>جنيه / م²</small></b><span>متوسط إرشادي مذكور في موجز العمل، وليس تسعيرًا ملزمًا لأي مشروع.</span></div><article><h2>كيف تستخدم هذا الرقم بشكل صحيح؟</h2><p>المتوسط لا يساوي تقييم المشروع. قد تزيد أو تنخفض القيمة مع الموقع الدقيق، مستوى التشطيب، إجمالي الدفعات، مساحة الوحدة، نسبة الإنشاء، ومصداقية موعد التسليم. لا تقارن سعرًا نقديًا بسعر تقسيط دون حساب التكلفة الإجمالية، ولا تستخدم متوسطًا عامًا لتبرير سعر أعلى في موقع لم تختبر خدماته.</p><p>الرقم المؤرخ مفيد لتحديد نطاق البحث الأولي. إذا كان عرض ما أعلى بكثير من المتوسط، فاسأل عن سبب الفرق: هل الموقع أكثر نضجًا؟ هل التشطيب أفضل؟ هل التسليم أقرب؟ هل الكثافة أقل؟ وإذا كان أقل بكثير، فاسأل أيضًا: هل المرافق غير مكتملة؟ هل نظام السداد يخفي تكلفة؟ هل موعد التسليم بعيد؟ السعر المنخفض ليس دائمًا فرصة، والسعر المرتفع ليس دائمًا جودة.</p><div class="note">تنبيه: نسبة الارتفاع السنوي (27.57%) المذكورة في موجز المشروع تستخدم كبيان تاريخي مؤرخ، وليست توقعًا أو توصية استثمارية. راجع مصدره وتاريخ القياس قبل الاعتماد عليه.</div></article></div></section><section class="section"><div class="wrap"><h2>جدول نطاقات استرشادية للمقارنة</h2><div class="data-table"><div><b>نوع البحث</b><b>ما الذي يغيّر السعر؟</b><b>سؤال المقارنة</b></div>${[["وحدة في حي قائم", "الحالة والتشطيب والخدمات", "ما تكلفة الانتقال الفعلية؟"], ["كمبوند تحت التنفيذ", "موعد التسليم والسداد والكثافة", "هل السعر يشمل كل الرسوم؟"], ["أرض أو طرح مبكر", "التخصيص والمرافق وزمن التطوير", "ما الخطوة التالية المكتوبة؟"], ["مقارنة مع التجمع / العاصمة", "القرب من العمل وبدائل النقل", "كم تدفع لكل دقيقة وصول؟"]].map(r=>`<div><span>${r[0]}</span><span>${r[1]}</span><span>${r[2]}</span></div>`).join("")}</div><h2>لماذا تختلف الأسعار داخل المدينة نفسها؟</h2><p>العبور الجديدة ليست سوقًا واحدًا متجانسًا. وحدة في نطاق خدماته قائمة تختلف عن وحدة في مشروع تحت الإنشاء، وأرض في مرحلة مبكرة تختلف عن شقة جاهزة. حتى داخل الكمبوند الواحد، قد تتغير القيمة مع الواجهة والدور والمساحة ونسبة الإطلالة وقرب الوحدة من الخدمات أو الطريق. لذلك لا تسأل فقط «كم سعر المتر؟» بل «ما الذي يشمله هذا السعر؟».</p><p>ابدأ بحساب التكلفة الكلية: سعر الوحدة، وديعة الصيانة، رسوم الإدارة، التشطيب إن لم يكن شاملًا، مصاريف التعاقد، وأي دفعات إضافية. ثم قارن هذه التكلفة ببدائل قابلة للزيارة. إذا كان المشروع يقدم تقسيطًا طويلًا، فاحسب الفرق بين السعر النقدي والسعر بالتقسيط؛ هذا الفرق هو تكلفة التمويل، ويجب أن تكون واضحة قبل اعتبار العرض مناسبًا.</p><h2>كيف تقرأ السعر مع الموقع والمطور؟</h2><p>السعر لا ينفصل عن الموقع ولا عن الجهة المنفذة. موقع قريب من محور لكنه يحتاج ربطًا صعبًا قد لا يستحق فرقًا كبيرًا. ومطور يقدم سعرًا جذابًا لكنه لا يوضح الإدارة أو التمويل أو نسبة البناء قد يحمل مخاطرة أعلى. لذلك يستخدم الدليل السعر كإشارة أولى، ثم يربطه بثلاثة أسئلة: أين تقع الوحدة؟ ما حالة التنفيذ؟ ومن يقف خلف المشروع؟</p><p>إذا كنت تقارن بين العبور الجديدة ومناطق أخرى، فلا تقارن السعر للمتر وحده. قارن زمن الوصول إلى وجهتك، مستوى الخدمات، موعد التسليم، وتكلفة التشغيل اليومية. أحيانًا تكون الوحدة الأعلى سعرًا أقل تكلفة على المدى الطويل إذا قللت وقت الطريق أو قدمت خدمات قائمة. وأحيانًا يكون الشراء المبكر مناسبًا إذا كان الخصم حقيقيًا والمستندات واضحة والمخاطرة محسوبة.</p><h2>كيف تبني جدول مقارنة خاصًا بك؟</h2><p>ضع كل عرض في صف مستقل، ثم سجّل السعر النقدي، السعر بالتقسيط، التكلفة الإجمالية، وديعة الصيانة، موعد التسليم، حالة التشطيب، ونسبة البناء. أضف بعد ذلك زمن الوصول إلى وجهتك اليومية وحالة الخدمات حول الموقع. عندما ترى الأرقام بجانب بعضها، يصبح من الأسهل ملاحظة أن عرضًا أقل سعرًا قد يكون أعلى تكلفة بسبب التمويل أو التشطيب أو بُعد الخدمات.</p><p>لا تحذف العروض التي تحتاج أسئلة؛ اجعل السؤال جزءًا من الجدول. إذا لم يوضح المطور رسوم الإدارة، اكتب «غير معلن». إذا كان موعد التسليم غير مكتوب، اكتب «يحتاج مستندًا». هذه الخانات الفارغة ليست ضعفًا في المقارنة؛ هي إشارة إلى ما يجب استكماله قبل التوقيع.</p><h2>قائمة مختصرة قبل قبول أي سعر</h2><ul class="check-list"><li>✓ اطلب السعر النقدي والسعر بالتقسيط والتكلفة الإجمالية لكل نظام.</li><li>✓ سجّل تاريخ عرض السعر، لأن السوق قد يتغير بين زيارة وأخرى.</li><li>✓ قارن الوحدات المتشابهة في المساحة والتشطيب وموعد التسليم فقط.</li><li>✓ اربط السعر بمرحلة الحي والخدمات الفعلية، لا باسم المدينة العام.</li><li>✓ راجع صفحة المطورين قبل اعتبار السعر مناسبًا أو مرتفعًا.</li></ul></div></section>${refsHtml()}</main>`;

const developersPage = `<main>${pageHero({tag:"دليل المطورين", eyebrow:"المقارنة الأهم", title:"دليل المطورين: الدليل قبل الدرجة", description:"لا تُفرض النتيجة على البيانات. نقيّم ما هو منشور وقابل للفحص، ونذكر حدود المعلومات المتاحة بوضوح."})}${atlasBody("مسار التحقق من المطور", "اتبع محطات التسليم والإدارة والتمويل والعقد والكثافة بدل الحكم من إعلان أو لقب واحد.")}<section class="paper section"><div class="wrap criteria">${[["01", "سابقة الأعمال المسلّمة", "وحدات قائمة يمكن زيارتها"], ["02", "إدارة ما بعد التسليم", "جهة إدارة وخبرة تشغيل محددة"], ["03", "الملاءة المالية", "شراكات أو تمويل معلن قابل للتحقق"], ["04", "شفافية التعاقد", "مواصفات وتكاليف مكتوبة"], ["05", "البناء والكثافة", "النسبة والارتفاعات وجودة المساحات"]].map(x=>`<div><b>${x[0]}</b><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join("")}</div></section><section class="section"><div class="wrap"><p class="eyebrow">جدول مرجعي</p><h2>النتيجة المجمّعة حسب البيانات المنشورة</h2><div class="table-wrap"><table><thead><tr><th>المطور</th><th>تسليم</th><th>إدارة</th><th>ملاءة</th><th>شفافية</th><th>كثافة</th><th>المجموع</th></tr></thead><tbody>${developers.map(d=>`<tr${d.featured ? ' class="featured"' : ""}><td><b>${d.name}</b><small>${d.source}</small></td><td>${d.delivery}</td><td>${d.management}</td><td>${d.finance}</td><td>${d.transparency}</td><td>${d.density}</td><td><strong>${d.total}<small>/5</small></strong></td></tr>`).join("")}</tbody></table></div><p class="caption">الدرجة من 5 إرشادية ومبنية على البيانات المنشورة المتاحة وقت التحديث. «قيد الاستكمال» ليست درجة سلبية؛ تعني أن الدليل العلني غير كافٍ للمقارنة الدقيقة.</p><h2>كيف نحسب الدرجة؟</h2><p>كل معيار يقيس جانبًا مختلفًا من المخاطرة. سابقة الأعمال المسلّمة تختبر قدرة المطور على تحويل الخطة إلى وحدات قائمة. إدارة ما بعد التسليم تختبر استمرارية الخدمة بعد البيع. الملاءة المالية تبحث عن مؤشرات تمويل أو شراكات معلنة. شفافية التعاقد تقيس وضوح المواصفات والتكاليف. أما نسبة البناء فتقرأ الكثافة والارتفاعات وجودة المساحات المفتوحة.</p><p>لا تُجمع الدرجات لإنتاج حكم نهائي مطلق؛ تُجمع لتساعدك على طرح أسئلة أدق. إذا حصل مطور على درجة مرتفعة في التسليم ومنخفضة في الشفافية، فالسؤال التالي هو طلب ملحق المواصفات وجدول التكلفة. وإذا حصل على درجة جيدة في الكثافة لكن بيانات الإدارة غير واضحة، فالسؤال هو من يدير المكان بعد التسليم وبأي ميزانية.</p></div></section><section class="olive section"><div class="wrap split"><article><span class="tag">⌖ بطاقة موثقة</span><h2>عوده للتطوير العقاري</h2><p>تذكر صفحة الشركة أكثر من 1,000 وحدة سكنية مسلّمة في العبور خلال أكثر من 25 عامًا، ومشروعات قائمة تشمل جولف سيتي وإيزيس كايرو ومباني الحي السادس والسابع. كما تذكر شراكة ملكية بنسبة 50% مع Bravo السعودية، وخبرتها وشهادات ISO المعلنة.[4] هذه العناصر تدعم درجات مرتفعة في التسليم والملاءة والإدارة، لأنها تقدم مؤشرات قابلة للفحص أكثر من وصف تسويقي عام.</p><p>بالنسبة لمعيار الكثافة، تذكر الشركة أن مشروع كناري في الحي 25 على 15 فدانًا وبنسبة بناء لا تتجاوز 25%. هذه معلومة مهمة لأنها تربط الكثافة برقم معلن، لكنها لا تلغي ضرورة مراجعة المخطط والارتفاعات والمساحات الخضراء ورسوم الإدارة. الدرجة المرتفعة هنا تعكس وضوح البيانات المنشورة، وليست بديلًا عن فحص العقد والموقع الفعلي.</p><a class="button" href="https://ouda-developments.com/why-ouda/" target="_blank" rel="noopener noreferrer">تعرّف أكثر على عوده ومشروع كناري ↗</a></article><aside class="evidence"><h2>ما الذي يمكن فحصه؟</h2><span>✓ زيارة مشروع قائم وحالته التشغيلية</span><span>✓ اسم جهة الإدارة وميزانية الصيانة</span><span>✓ شراكة التمويل ومستنداتها</span><span>✓ ملحق المواصفات والتكلفة</span><span>✓ نسبة البناء والمخطط المعتمد</span></aside></div></section><section class="section"><div class="wrap"><h2>شرح مختصر لكل فئة في الجدول</h2>${developers.map(d=>`<article class="developer-note"><h3>${d.name}</h3><p>${d.note}</p></article>`).join("")}<h2>كيف تستخدم الجدول دون أن تتحول الدرجة إلى إعلان؟</h2><p>ابدأ بالمعيار الأكثر ارتباطًا بمخاطرتك. إذا كنت تشتري للسكن القريب، فالتسليم والإدارة أهم من وعد مستقبلي. إذا كنت تشتري مبكرًا، فالملاءة وشفافية التعاقد تصبح أكثر حساسية. وإذا كنت تهتم بجودة الحياة داخل المشروع، فنسبة البناء والارتفاعات والمساحات المفتوحة يجب أن تكون جزءًا من المقارنة.</p><p>لا تقبل درجة دون دليل، ولا تقبل دليلًا دون تاريخ. البيانات المنشورة قد تتغير، والمشروعات تنتقل من مرحلة إلى أخرى. لذلك يذكر الدليل مصدر كل صف، ويطلب منك تحويل أي معلومة مهمة إلى مستند قبل التوقيع. المقارنة الجيدة لا تبحث عن «أفضل اسم»، بل عن أفضل توافق بين الموقع والمطور والتكلفة والهدف.</p></div></section>${refsHtml()}</main>`;

const buying = `<main>${pageHero({tag:"دليل الشراء", eyebrow:"قرار قابل للتدقيق", title:"دليل شراء هادئ: من الهدف إلى العقد", description:"رتّب القرار في خطوات. لا يدفعك عرض سعر أو موعد محدود لتجاوز فحص الموقع والوثائق."})}${atlasBody("خط قرار الشراء", "كل محطة أدناه تقلل مخاطرة مختلفة: الهدف، الموقع، المعاينة، الوثائق، التكلفة، ثم المقارنة المكتوبة.")}<section class="paper section"><div class="wrap buy-grid">${[["01", "حدد الهدف والزمن", "سكن قريب أم استثمار بأفق أطول؟ هذا يحدد الحي ونوع الوحدة."], ["02", "اختصر المواقع", "قارن 3 خيارات متشابهة بدل عشرات الإعلانات غير المتجانسة."], ["03", "عاين في وقتين", "زر في يوم عمل وفي وقت ذروة لتفهم الطريق والخدمات."], ["04", "راجع الأرض والترخيص", "اطلب تخصيص الأرض والترخيص والمخطط والالتزامات المكتوبة."], ["05", "اقرأ العقد كتكلفة كلية", "السعر، الصيانة، التسليم، الغرامات، والتشطيب يجب أن تكون واضحة."], ["06", "احتفظ بمقارنة مكتوبة", "التوثيق البسيط يحميك من القرار العاطفي أو ضغط المبيعات."]].map(x=>`<article><b>${x[0]}</b><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join("")}</div></section><section class="section"><div class="wrap content-grid"><article><h2>ابدأ بالهدف قبل الإعلان</h2><p>أكثر أخطاء الشراء شيوعًا أن يبدأ الباحث من عرض جذاب ثم يحاول تكييف احتياجه معه. الطريقة الأهدأ هي العكس: حدد هدفك أولًا. هل تريد سكنًا خلال سنة؟ هل تبحث عن وحدة للعائلة قرب مدارس وخدمات؟ هل تقبل شراءً مبكرًا مقابل سعر أقل؟ كل إجابة تغير نوع الحي ونوع المطور ونوع المخاطرة المناسبة.</p><p>بعد تحديد الهدف، اكتب ميزانية كلية لا سعرًا أوليًا فقط. أضف وديعة الصيانة ورسوم الإدارة والتشطيب والانتقال وأي دفعات مؤجلة. ثم حدد وجهاتك اليومية وقِس الوصول إليها. بهذه الطريقة يصبح لديك إطار قرار قبل أن تدخل مكتب مبيعات أو تقرأ إعلانًا جديدًا.</p><h2>المعاينة ليست زيارة شكلية</h2><p>زر الموقع في يوم عمل وفي وقت ذروة، وإن أمكن في المساء أيضًا. انظر إلى الرصف والإضاءة والمياه والكهرباء ومحلات اليوم العادي، واسأل عن الاستخدامات المجاورة. إذا كان المشروع تحت الإنشاء، فلا تكتفِ بماكيت أو صورة؛ اطلب موقع القطعة بالضبط، ومرحلة المرافق، وموعد التسليم المكتوب.</p><p>أثناء المعاينة، سجّل ملاحظات قابلة للمقارنة: زمن الوصول، حالة الشارع، مستوى الضوضاء، قرب الخدمات، وحالة المباني المجاورة. لا تعتمد على الانطباع العام فقط. الهدف هو تحويل الزيارة إلى بيانات يمكن مراجعتها عندما تقارن بين ثلاثة خيارات متشابهة.</p><h2>الوثائق قبل الحماس</h2><p>اطلب تخصيص الأرض والترخيص والمخطط والالتزامات المكتوبة. راجع مساحة الوحدة الصافية، جدول الدفعات، موعد التسليم، حالة التشطيب، وديعة الصيانة، رسوم الإدارة، الغرامات، وآلية حل النزاع. أي بند غير واضح يجب توضيحه كتابةً قبل دفع مبالغ كبيرة. إذا كان العرض يعتمد على «ثقة» بدل مستند، فهذه إشارة تحتاج توقفًا.</p><p>لا تخلط بين السعر والتكلفة. السعر رقم في الإعلان، أما التكلفة فهي كل ما ستدفعه حتى تسكن أو تدير الوحدة. قارن السعر النقدي بالتقسيط، واحسب الفرق كتكلفة تمويل. ثم اربط النتيجة بموقع الوحدة وحالة التنفيذ وسابقة المطور. القرار الجيد ليس الأرخص دائمًا، بل الأكثر وضوحًا وتوازنًا مع هدفك.</p><h2>كيف تتعامل مع ضغط المبيعات؟</h2><p>إذا سمعت أن العرض «ينتهي اليوم» أو أن الوحدة «آخر فرصة»، فاطلب المستندات نفسها بهدوء. العرض الجيد يتحمل المراجعة، والمشروع الواضح لا يحتاج إلى منعك من المقارنة. اطلب مهلة لقراءة العقد، ولا تدفع مبلغًا كبيرًا قبل استلام نسخة كاملة من الشروط. إذا تغيرت الإجابة بين مكالمة وزيارة، فسجّل ذلك في ورقة المقارنة.</p><p>يمكنك أيضًا استخدام سؤال مباشر: «ما الذي يجعل هذا العرض مناسبًا لهدفي أنا؟» إذا كانت الإجابة عامة، فارجع إلى إطارك: الموقع، التكلفة، التسليم، الإدارة، والكثافة. وإذا كانت الإجابة محددة، فاطلب إثباتها كتابةً. هذه الطريقة تحول الحوار من إقناع إلى توثيق.</p><p>قبل التوقيع، راجع نسخة العقد في وقت هادئ وقارنها بما سمعته في المعاينة. إذا اختلف بند واحد مؤثر، فاطلب تعديله كتابةً أو تأجيل الدفع حتى يتضح. الالتزام العقاري طويل، وخطوة مراجعة إضافية أقل تكلفة من محاولة تصحيح سوء فهم بعد التعاقد.</p><h2>كيف تغلق القرار دون استعجال؟</h2><p>بعد المعاينة والمستندات، امنح نفسك مراجعة أخيرة قبل التوقيع. قارن أفضل خيارين على ورقة واحدة، واكتب سبب اختيارك بلغة عملية: زمن وصول أقل، تكلفة كلية أوضح، إدارة معلنة، أو نسبة بناء مناسبة. إذا لم تستطع كتابة سبب واضح، فالقرار لم ينضج بعد. الهدف ليس إبطاء الشراء لمجرد التأجيل، بل منع الانتقال من حماس الإعلان إلى التزام طويل دون دليل كافٍ.</p><h2>الأسئلة الخمسة لأي مطور</h2><ul class="check-list"><li>✓ <b>السابقة:</b> أين مشروع مسلّم يمكن زيارته؟</li><li>✓ <b>الإدارة:</b> من يدير المكان بعد التسليم؟</li><li>✓ <b>التمويل:</b> ما أساس تمويل التنفيذ؟</li><li>✓ <b>العقد:</b> ما المواصفات والتكاليف المكتوبة؟</li><li>✓ <b>الكثافة:</b> ما نسبة البناء والارتفاعات؟</li></ul><a class="text-link" href="https://ouda-developments.com/%D9%83%D9%8A%D9%81-%D8%AA%D8%AE%D8%AA%D8%A7%D8%B1-%D8%A3%D9%81%D8%B6%D9%84-%D9%85%D8%B7%D9%88%D8%B1-%D8%B9%D9%82%D8%A7%D8%B1%D9%8A-%D9%81%D9%8A-%D8%A7%D9%84%D8%B9%D8%A8%D9%88%D8%B1-%D8%A7%D9%84%D8%AC/" target="_blank" rel="noopener noreferrer">مقال تفصيلي: كيف تختار مطورًا عقاريًا ↗</a></article><aside class="action-card"><p>قارن قبل أن تلتزم</p><a class="button" href="/developers/">قارن المطورين ↖</a><a class="text-link" href="/prices/">افتح دليل قراءة الأسعار ↖</a><a class="text-link" href="/districts/">اختصر الأحياء المناسبة ↖</a></aside></div></section>${refsHtml()}</main>`;

const faq = `<main>${pageHero({tag:"الأسئلة الشائعة", eyebrow:"إجابات قابلة للاقتباس", title:"أسئلة شائعة عن العبور الجديدة", description:"إجابات مختصرة تشرح الصورة دون أن تتجاوز حدود ما يمكن التحقق منه. ارجع للمصدر أو للزيارة الميدانية في القرار النهائي."})}${atlasBody("فهرس الإجابات", "ابدأ بالسؤال الذي يحدد موقعك في مسار القرار، ثم انتقل إلى المصدر أو المعاينة قبل الالتزام.")}<section class="paper section"><div class="wrap narrow"><div class="faq-list">${faqs.map(([q,a],i)=>`<details${i===0 ? " open" : ""}><summary>${q}<span>⌄</span></summary><p>${a}</p></details>`).join("")}</div><div class="related"><a href="/developers/">كيف نقارن المطورين؟ ↖</a><a href="/transport/">دليل المواصلات ↖</a><a href="/buying-guide/">خطوات الشراء ↖</a></div></div></section>${refsHtml()}</main>`;

